def distribute(base, remainders, seats):
    # base: dict of current allocations
    # remainders: dict of remainders for each name
    # seats: total seats to allocate
    result = dict(base)
    allocated = sum(result.values())
    remaining = seats - allocated
    if remaining <= 0:
        return {k: result[k] for k in sorted(result)}
    # Sort names by descending remainder, then ascending name
    sorted_names = sorted(base.keys(), key=lambda k: (-remainders[k], k))
    for name in sorted_names:
        if remaining == 0:
            break
        result[name] += 1
        remaining -= 1
    return {k: result[k] for k in sorted(result)}

